import {DESTINATIONS, destination, renderPlatformOptions} from './platforms.js';
const encode = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds = {audience_review:'Review audience fit',draft_suggestions:'Suggest outreach drafts'};
const triggers = {manual:'Run when you choose',on_import:'After a CSV import'};

export function renderAutomationView({workflows=[],runs=[],schedules=[],schedulingAvailable=false,configured=false,signedIn=false,operation='',escape=encode}={}) {
  const e=escape;
  if(!configured||!signedIn)return `<section class="panel"><div class="empty-state"><div class="empty-icon" aria-hidden="true">↻</div><h3>${configured?'Make your repeated work easier.':'Cloud automations need setup.'}</h3><p>${configured?'Sign in and save a cloud workspace to create private workflows for audience review and outreach drafts.':'Automations are not available on this deployment yet. Your local prospect review and drafting tools still work.'}</p><button class="button primary" data-action="account">${configured?'Sign in to create workflows':'View cloud setup'}</button></div></section>`;
  return `<div id="automation-operation-status" class="operation-status" role="status" aria-live="polite" ${operation?'':'hidden'}>${e(operation)}</div>${renderAutomationDashboard({workflows,runs,schedules,schedulingAvailable,escape:e})}<div class="outreach-intro"><span class="badge review">Review and drafting only</span><p>Choose the platform you ultimately want to use. Pull organizes the evidence and prepares drafts. Nothing sends messages automatically. Scheduled review and drafting can run while Pull is closed. Sending remains a separate, explicit approval through a permitted connected channel.</p><button class="link-button" data-action="automation-refresh">Refresh workflows</button></div>
  <div class="section-grid"><section class="panel"><div class="panel-head"><div><h2>Create a workflow</h2><p>Repeat a useful step, while keeping your decisions in view.</p></div></div><form id="automation-form" class="audience-form"><div class="field"><label for="automation-name">Workflow name</label><input id="automation-name" name="name" maxlength="100" required placeholder="Review my next imported list"></div><div class="field"><label for="automation-kind">What should it do?</label><select id="automation-kind" name="kind"><option value="audience_review">Review audience fit</option><option value="draft_suggestions">Suggest outreach drafts</option></select><small>Audience review reports matches and evidence gaps. Draft suggestions use only your reviewed, eligible shortlist and keep existing drafts.</small></div><div class="field"><label for="automation-destination">Where will you use the result?</label><select id="automation-destination" name="destination">${renderPlatformOptions('none',e)}</select><small>Pull prepares a reviewed handoff. This choice does not connect or send through that platform.</small></div><div class="field"><label for="automation-trigger">When should it run?</label><select id="automation-trigger" name="trigger"><option value="manual">When I choose Run</option><option value="on_import">After I import a CSV (save to cloud)</option></select><small>After-import workflows save new imported data to your private cloud account and run while this app is open.</small></div><p id="automation-error" class="form-error" role="alert"></p><div class="form-actions"><button class="button primary" type="submit">Create workflow</button></div></form></section>
  <section class="panel automation-workflows"><div class="panel-head"><div><h2>Your workflows</h2><p>${workflows.length} active ${workflows.length===1?'workflow':'workflows'}</p></div></div>${workflows.length?workflows.map(w=>`<article class="draft-card automation-card" data-motion-key="workflow:${e(w.id)}"><div class="draft-meta"><div><h3>${e(w.name)}</h3><small>${e(kinds[w.kind]||'Workflow')} · ${e(triggers[w.trigger]||'Manual')} · ${e(destination(w.destination).name)}</small></div><span class="badge ${w.enabled?'fit':'review'}">${w.enabled?'Enabled':'Paused'}</span></div><p class="small-print"><strong>${e(destination(w.destination).path)}.</strong> ${e(destination(w.destination).note)}</p><p class="small-print">${w.kind==='audience_review'?'Reports fit against your saved audience. Your shortlist approvals stay yours.':'Creates editable template drafts for reviewed matches. Existing messages stay intact; new drafts need your review.'}</p><div class="draft-actions"><button class="button secondary small" data-action="automation-schedule" data-automation-id="${e(w.id)}" ${w.enabled&&schedulingAvailable?'':'disabled'}>Schedule</button><button class="button primary small" data-action="automation-run" data-automation-id="${e(w.id)}" ${w.enabled?'':'disabled'}>Run now</button><button class="button secondary small" data-action="automation-toggle" data-automation-id="${e(w.id)}" data-enabled="${w.enabled?'false':'true'}">${w.enabled?'Pause':'Enable'}</button><button class="link-button" data-action="automation-archive" data-automation-id="${e(w.id)}">Archive</button></div></article>`).join(''):'<div class="empty-results"><p class="small-print">Create your first workflow to make audience review or drafting repeatable.</p></div>'}</section></div>
  <section class="panel automation-schedules"><div class="panel-head"><div><h2>Background review schedules</h2><p>${schedulingAvailable?'Runs saved audience review or draft preparation. No messages are sent.':'Background scheduling is awaiting server setup. Run now remains available.'}</p></div></div>${schedules.length?schedules.map(s=>`<article class="draft-card"><h3>${e(workflows.find(w=>w.id===s.workflow_id)?.name||'Workflow')}</h3><p>Every ${e(s.interval_seconds/3600)} hours · ${s.enabled?'Enabled':'Paused'} · next ${e(new Date(s.next_run_at).toLocaleString())}</p><p class="small-print">Last result: ${e(s.last_status||'Not run yet')}${s.last_revision?' · cloud revision '+e(s.last_revision):''}</p><button class="button secondary small" data-action="automation-schedule-toggle" data-schedule-id="${e(s.id)}" data-enabled="${s.enabled?'false':'true'}">${s.enabled?'Pause schedule':'Resume schedule'}</button></article>`).join(''):'<p class="small-print">Choose Schedule on a workflow to approve recurring review or drafting.</p>'}</section>
  <section class="panel activity-panel"><div class="panel-head"><div><h2>Social outreach, with clear boundaries</h2><p>Pull can work automatically before a message leaves your account.</p></div></div><div class="platform-catalog">${DESTINATIONS.filter(item=>['x','linkedin','facebook','instagram'].includes(item.id)).map(item=>`<article><span>Automated in Pull</span><h3>${e(item.name)}</h3><p>Review fit, remove duplicates and exclusions, and prepare a channel-specific draft after import.</p><small>${e(item.path)}. ${e(item.note)} No account is connected yet.</small></article>`).join('')}</div><p class="small-print" style="padding:0 24px 24px">A future connected reply or publishing action needs the platform’s approved API, the right account permissions, verified conversation eligibility, and a server-side opt-out check. Scheduling gaps alone do not grant permission to message someone.</p></section>
  <section class="panel activity-panel"><div class="panel-head"><div><h2>Choose a destination</h2><p>Start with the platform your customers already use.</p></div></div><div class="platform-catalog">${DESTINATIONS.filter(item=>item.id!=='none').map(item=>`<article><span>${e(item.group)}</span><h3>${e(item.name)}</h3><p>${e(item.note)}</p><small>${e(item.path)}</small></article>`).join('')}</div></section>
  <section class="panel activity-panel automation-receipts"><div class="panel-head"><div><h2>Recent completed runs</h2><p>The latest 20 committed runs. A completed workflow does not mean a message was sent.</p></div></div>${runs.length?`<ol class="activity-list">${runs.map(r=>`<li><span class="activity-symbol" aria-hidden="true">✓</span><div><strong>${e(r.name||'Workflow')}</strong><p>${r.kind==='draft_suggestions'?`${e(r.counts?.drafts_created??0)} draft suggestions added; ${e(r.counts?.existing_drafts??0)} existing drafts kept.`:`${e(r.counts?.matches??0)} matches; ${e(r.counts?.needs_evidence??0)} need evidence; ${e(r.counts?.excluded??0)} excluded.`}</p></div><span class="activity-time"><time datetime="${e(r.created_at)}">${e(new Date(r.created_at).toLocaleString())}</time><small>${r.counts?.data_origin==='example'?'Fictional example · ':''}Cloud revision ${e(r.result_revision)}</small></span></li>`).join('')}</ol>`:'<div class="empty-results"><p class="small-print">Run history appears after a workflow and its cloud save commit successfully.</p></div>'}</section>`;
}

export function renderAutomationDashboard({workflows=[],runs=[],schedules=[],schedulingAvailable=false,escape=encode}={}) {
 const e=escape,active=workflows.filter(w=>w.enabled).length,scheduled=schedules.filter(s=>s.enabled).length;
 const attention=schedules.filter(s=>['failed','workflow_unavailable','workspace_unavailable'].includes(s.last_status));
 const latest=[...runs].sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at))[0];
 return `<section class="panel automation-overview" aria-labelledby="automation-dashboard-title"><div class="panel-head"><div><p class="eyebrow">AUTOMATION / OVERVIEW</p><h2 id="automation-dashboard-title">Your workflow dashboard</h2><p>Prepare the next step. Keep every outcome in view.</p></div><button class="button secondary small" data-action="automation-refresh">Refresh status</button></div><dl class="automation-metrics"><div><dt>Enabled workflows</dt><dd>${active}<small>of ${workflows.length} saved</small></dd></div><div><dt>Background schedules</dt><dd>${scheduled}<small>${schedulingAvailable?'active schedules':'server setup pending'}</small></dd></div><div><dt>Completed runs</dt><dd>${runs.length}<small>in the latest 20 receipts</small></dd></div><div><dt>Needs attention</dt><dd>${attention.length}<small>schedule exceptions</small></dd></div></dl><div class="automation-next"><span class="badge ${attention.length?'review':'fit'}">${attention.length?'Review needed':latest?'Last run committed':'Ready to begin'}</span><p>${attention.length?'A scheduled workflow needs attention. Check its status below; your saved workspace is preserved.':latest?`${e(latest.name||'Workflow')} completed at ${e(new Date(latest.created_at).toLocaleString())}. Review the output before outreach.`:'Create an audience review or drafting workflow below, then choose Run now.'}</p></div><details class="automation-boundaries"><summary>How execution works</summary><ol><li>Save your audience and prospect list.</li><li>Run a workflow now, or approve an available recurring schedule.</li><li>Review the committed result and its cloud revision in run history.</li><li>Sending requires a connected permitted channel and separate approval.</li></ol></details></section>`;
}
